begin;
alter table public.curriculum_subjects add column if not exists is_published boolean not null default false;
alter table public.curriculum_subjects add column if not exists completion_percent integer not null default 0 check (completion_percent between 0 and 100);
alter table public.curriculum_subjects add column if not exists icon_key text not null default 'science';
alter table public.curriculum_subjects add column if not exists accent text not null default 'cyan';
alter table public.curriculum_modules add column if not exists code text;
alter table public.curriculum_modules add column if not exists section_number integer not null default 0;
alter table public.curriculum_modules add column if not exists is_complete boolean not null default false;
alter table public.curriculum_topics add column if not exists code text;
alter table public.curriculum_topics add column if not exists lesson_text text not null default '';
alter table public.curriculum_topics add column if not exists worked_solution text not null default '';
alter table public.curriculum_topics add column if not exists diagnostic_quiz jsonb not null default '[]'::jsonb;
alter table public.curriculum_topics add column if not exists antx_reward_trigger text not null default '';
alter table public.curriculum_topics add column if not exists is_complete boolean not null default false;
create unique index if not exists curriculum_modules_subject_code_uq on public.curriculum_modules(subject_id, code);
create unique index if not exists curriculum_topics_module_code_uq on public.curriculum_topics(module_id, code);
create table if not exists public.curriculum_topic_nodes (id uuid primary key default gen_random_uuid(), topic_id uuid not null references public.curriculum_topics(id) on delete cascade, code text not null, node_type text not null check (node_type in ('lesson','worked_solution','quiz')), title text not null, content text not null default '', sort_order integer not null default 0, is_complete boolean not null default false, created_at timestamptz not null default now());
create unique index if not exists curriculum_topic_nodes_topic_code_uq on public.curriculum_topic_nodes(topic_id, code);
alter table public.curriculum_topic_nodes enable row level security;
drop policy if exists "curriculum topic nodes are publicly readable" on public.curriculum_topic_nodes;
create policy "curriculum topic nodes are publicly readable" on public.curriculum_topic_nodes for select using (true);
revoke insert, update, delete on public.curriculum_topic_nodes from anon, authenticated;
grant select on public.curriculum_topic_nodes to anon, authenticated;
grant all on public.curriculum_topic_nodes to service_role;
do $$
declare
  math_id uuid; it_id uuid; module_id uuid; topic_id uuid;
begin
  select id into math_id from public.curriculum_subjects where code='MATH';
  select id into it_id from public.curriculum_subjects where code='IT';

end $$;
commit;
